import {
    BooleanColumn,
    StringColumn,
    ReferenceColumn,
    DecimalColumn,
    TranslatedFieldColumn,
    Table,
    DomainIdColumn,
    DomainPathColumn,
    GenericColumn,
    UserRolesColumn,
} from '../../db'

export const sys_app_application = Table({
    name: 'sys_app_application',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({ mandatory: false, label: 'Active', read_only: false, active: true, default: true }),
        category: ReferenceColumn({
            mandatory: false,
            label: 'Category',
            read_only: false,
            active: true,
            referenceTable: 'sys_app_category',
        }),
        description: StringColumn({
            mandatory: false,
            label: 'Description',
            read_only: false,
            active: true,
            maxLength: 4000,
            dropdown: 'none',
        }),
        device_type: StringColumn({
            mandatory: false,
            label: 'Device type',
            read_only: false,
            active: true,
            default: 'browser',
            maxLength: 40,
            dropdown: 'dropdown_without_none',
            choices: {
                any: { label: 'Any', inactive: false, language: 'en' },
                browser: { label: 'Browser', inactive: false, language: 'en' },
                mobile: { label: 'Mobile', inactive: false, language: 'en' },
            },
        }),
        hint: TranslatedFieldColumn({ mandatory: false, label: 'Hint', read_only: false, active: true }),
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
        order: DecimalColumn({ mandatory: false, label: 'Order', read_only: false, active: true }),
        roles: UserRolesColumn({ mandatory: false, label: 'Roles', read_only: false, active: true }),
        sys_domain: DomainIdColumn({
            mandatory: false,
            label: 'Domain',
            read_only: false,
            active: true,
            default: 'global',
        }),
        sys_domain_path: DomainPathColumn({
            mandatory: false,
            label: 'Domain Path',
            read_only: false,
            active: true,
            default: '/',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        sys_overrides: ReferenceColumn({
            mandatory: false,
            label: 'Overrides',
            read_only: false,
            active: true,
            referenceTable: 'sys_app_application',
        }),
        title: TranslatedFieldColumn({ mandatory: true, label: 'Title', read_only: false, active: true }),
        view_name: StringColumn({
            mandatory: false,
            label: 'View name',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
    },
})
